/// <summary>
/// Gets or sets <c>token</c>.
/// </summary>
/// <param name = "_token"> <c>token</c></param>
/// <returns> <c>token</c>. </returns>
public str parmToken(str _token = token)
{
    token = _token;
    return token;
}

/// <summary>
/// Gets or sets <c>url</c>.
/// </summary>
/// <param name = "_token"> <c>url</c></param>
/// <returns> <c>url</c>. </returns>
public str parmUrl(str _url = url)
{
    url = _url;
    return url;
}

public Binary parmContent(Binary _content = content)
{
    content = _content;
    return content;
}

public str parmJsonContent(str _jsonContent = jsonContent)
{
    jsonContent = _jsonContent;
    return jsonContent;
}

public str parmContentType(str _contentType = contentType)
{
    contentType = _contentType;
    return contentType;
}

public str parmHeader(str _header = header)
{
    header = _header;
    return header;
}

public str parmMethod(str _method = method)
{
