public boolean validateCustomerAddress()
{
    boolean             customerAddressValid;
    RetailWebResponse   response;
    str                 rawResponse, ref;
    Map                 responseData;

    RetailWebResponse RetailWebResponse = this.Getresponse();

    return customerAddressValid;
}

private RetailWebResponse Getresponse()
{
    System.Net.HttpWebRequest request = null;
    System.Net.HttpWebResponse response = null;
    CLRObject webResponse;
    System.Net.WebHeaderCollection headers;
    System.IO.MemoryStream stream;
    Binary requestContent;
    str responseData;
    System.Exception ex;
    System.Net.WebException webException;
    RetailWebResponse retailWebResponse;
    int httpStatusCode;

    System.IO.Stream             requestStream;
    System.IO.StreamWriter       streamWriter;
    System.IO.StreamReader       streamReader;
    System.Text.Encoding         encoding;
    str                          responseContent;

    try
    {
        request = System.Net.WebRequest::Create(this.parmUrl()) as System.Net.HttpWebRequest;

        if (strLen(this.parmMethod()) > 0)
        {
            request.set_Method(this.parmMethod());
        }

        headers = request.get_Headers();
        if (strLen(this.parmHeader()) > 0)
        {
            headers.Add(this.parmHeader());
        }

        if (strLen(this.parmApim()) > 0)
        {
            headers.Add(this.parmApim());
        }

        if (strLen(this.parmContentType()) > 0)
        {
            request.set_ContentType(this.parmContentType());
        }

        encoding = System.Text.Encoding::UTF8;
        request.set_ContentLength(encoding.GetByteCount(this.parmJsonContent()));

        if (this.parmJsonContent())
        {
            stream = new System.IO.MemoryStream(encoding.GetBytes(this.parmJsonContent()));
            METKleberRequestAndResponseHelper::writeRequestData(request, stream.ToArray());
        }

        webResponse = request.GetResponse();
        response = webResponse as System.Net.HttpWebResponse;
    }
    catch (Exception::CLRError)
    {
        ex = ClrInterop::getLastException();
        if (ex != null)
        {
            ex = ex.get_InnerException();
            if ((ex != null) && (ex is System.Net.WebException))
            {
                webException = ex as System.Net.WebException;
                webResponse = webException.get_Response();
                response = webResponse as System.Net.HttpWebResponse;
            }
        }
    }

    responseData = METKleberRequestAndResponseHelper::readResponseData(response);
    response.Close();

    httpStatusCode = response.get_StatusCode();

    contentType = response.get_ContentType();
    retailWebResponse = new RetailWebResponse(httpStatusCode, responseData, contentType);

    return retailWebResponse;
}

private static void writeRequestData(System.Net.HttpWebRequest _request, System.Byte[] _bytes)
{
    System.IO.Stream stream;

    _request.set_ContentLength(_bytes.get_Length());

    stream = _request.GetRequestStream();
    stream.Write(_bytes, 0, _bytes.get_Length());
    stream.Close();
}

private static str readResponseData(System.Net.HttpWebResponse response)
{
    int batchSize = 1024;
    System.IO.Stream receiveStream;
    System.IO.StreamReader readStream;
    System.Text.Encoding encode;
    System.Char[] read;
    System.Text.StringBuilder sb;
    System.String readString;
    str contentEncoding;

    int countRead;

    if (response == null)
    {
        return "";
    }

    receiveStream = response.GetResponseStream();
    contentEncoding = response.get_ContentEncoding();
    if (contentEncoding)
    {
        encode = System.Text.Encoding::GetEncoding(contentEncoding);
    }
    else
    {
        encode = new System.Text.UTF8Encoding();
    }

    readStream = new System.IO.StreamReader(receiveStream, encode);
    read = new System.Char[batchSize]();

    countRead = readStream.Read(read, 0, batchSize);

    sb = new System.Text.StringBuilder();
    while (countRead > 0)
    {
        readString = new System.String(read, 0, countRead);
        sb.Append(readString);
        countRead = readStream.Read(read, 0, batchSize);
    }

    readStream.Close();

    return sb.ToString();
}
